def create_llm_span(self, completion_content: str):
    """Create an LLM span pairing the first pending prompt with a completion."""
    prompt_data = self.pending_prompts.pop(0) if self.pending_prompts else None
    prompt_role, prompt_content = prompt_data if prompt_data else (None, None)
    prompt_time = self.prompt_start_time
    self.prompt_start_time = time.time_ns() if self.pending_prompts else None
    agent_name = self.prompt_agent_name
    if not self.pending_prompts:
        self.prompt_agent_name = None

    parent_context = self._get_parent_context(agent_name)

    agent_start = self.agent_start_times.get(agent_name) if agent_name else None
    if agent_start and prompt_time:
        start_time = max(agent_start, prompt_time)
    elif agent_start:
        start_time = agent_start
    elif prompt_time:
        start_time = prompt_time
    else:
        start_time = time.time_ns()

    model_name_str = (
        str(self.model_name) if self.model_name else "gpt-4o-realtime-preview"
    )

    span = self.tracer.start_span(
        "openai.realtime",
        kind=SpanKind.CLIENT,
        context=parent_context,
        start_time=start_time,
        attributes={
            GenAIAttributes.GEN_AI_OPERATION_NAME: "realtime",
            GenAIAttributes.GEN_AI_PROVIDER_NAME: "openai",
            GenAIAttributes.GEN_AI_REQUEST_MODEL: model_name_str,
        },
    )

    span.set_attribute(
        GenAIAttributes.GEN_AI_RESPONSE_MODEL, model_name_str,
    )

    if self.pending_usage:
        if self.pending_usage.get("input_tokens"):
            span.set_attribute(
                GenAIAttributes.GEN_AI_USAGE_INPUT_TOKENS,
                self.pending_usage["input_tokens"],
            )
        if self.pending_usage.get("output_tokens"):
            span.set_attribute(
                GenAIAttributes.GEN_AI_USAGE_OUTPUT_TOKENS,
                self.pending_usage["output_tokens"],
            )
        if self.pending_usage.get("total_tokens"):
            span.set_attribute(
                SpanAttributes.GEN_AI_USAGE_TOTAL_TOKENS,
                self.pending_usage["total_tokens"],
            )
        self.pending_usage = None

    if should_send_prompts():
        if prompt_content:
            input_msg = {
                "role": prompt_role or "user",
                "parts": [{"type": "text", "content": prompt_content}],
            }
            span.set_attribute(
                GenAIAttributes.GEN_AI_INPUT_MESSAGES,
                json.dumps([input_msg]),
            )

        out_msg = {
            "role": "assistant",
            "parts": [{"type": "text", "content": completion_content}],
            "finish_reason": "",
        }
        span.set_attribute(
            GenAIAttributes.GEN_AI_OUTPUT_MESSAGES,
            json.dumps([out_msg]),
        )

    # Realtime API does not provide finish reasons; set top-level
    # attribute only when a meaningful value is available (consistent
    # with _hooks.py which omits the attribute when mapped value is None).

    span.set_status(Status(StatusCode.OK))
    span.end()

    self.llm_call_index += 1
    return span

def _get_parent_context(self, agent_name: Optional[str] = None):
    """Get parent context from agent spans or workflow span.

    Looks up the parent context in this order:
    1. Specified agent_name in active agent_spans
    2. Specified agent_name in agent_span_contexts
    3. Current agent in agent_span_contexts
    4. Workflow span
    """
    target = agent_name or self.current_agent_name
    if target:
        if target in self.agent_spans:
            return set_span_in_context(self.agent_spans[target])
        if target in self.agent_span_contexts:
            return self.agent_span_contexts[target]
    if self.workflow_span:
        return set_span_in_context(self.workflow_span)
    return None

def _set_span_attribute(span, name, value):
    if value is None or value == "":
        return

    if hasattr(openai, "NOT_GIVEN") and value == openai.NOT_GIVEN:
        return

    span.set_attribute(name, value)

async def _handle_request(span, kwargs, instance):
    _set_request_attributes(span, kwargs, instance)
    _set_client_attributes(span, instance)
    if should_emit_events():
        for message in kwargs.get("messages", []):
            emit_event(
                MessageEvent(
                    content=message.get("content"),
                    role=message.get("role"),
                    tool_calls=_parse_tool_calls(
                        message.get("tool_calls", None)),
                )
            )
    else:
        if should_send_prompts():
            await _set_prompts(span, kwargs.get("messages"))
            if kwargs.get("functions"):
                _set_functions_attributes(span, kwargs.get("functions"))
            elif kwargs.get("tools"):
                set_tools_attributes(span, kwargs.get("tools"))
    if Config.enable_trace_context_propagation:
        propagate_trace_context(span, kwargs)

    # Reasoning request attributes
    reasoning_effort = kwargs.get("reasoning_effort")
    _set_span_attribute(
        span,
        SpanAttributes.GEN_AI_REQUEST_REASONING_EFFORT,
        reasoning_effort,
    )

def _is_suppressed():
    return context_api.get_value(_SUPPRESS_INSTRUMENTATION_KEY) or context_api.get_value(
        SUPPRESS_LANGUAGE_MODEL_INSTRUMENTATION_KEY
    )

def _instrumented_model_invoke(fn, tracer, metric_params, event_logger):
    @wraps(fn)
    def with_instrumentation(*args, **kwargs):
        if context_api.get_value(SUPPRESS_LANGUAGE_MODEL_INSTRUMENTATION_KEY):
            return fn(*args, **kwargs)

        (provider, _model_vendor, _model) = _get_vendor_model(kwargs.get("modelId"))
        operation_name = _derive_operation_name(kwargs)
        span_attributes = {
            GenAIAttributes.GEN_AI_PROVIDER_NAME: provider,
            GenAIAttributes.GEN_AI_OPERATION_NAME: operation_name,
            GenAIAttributes.GEN_AI_REQUEST_MODEL: _model,
        }
        with tracer.start_as_current_span(
            _span_name(operation_name, _model), kind=SpanKind.CLIENT, attributes=span_attributes,
            record_exception=False, set_status_on_exception=False,
        ) as span:
            try:
                response = fn(*args, **kwargs)
            except Exception as e:
                span.set_attribute(ERROR_TYPE, e.__class__.__name__)
                span.record_exception(e)
                span.set_status(Status(StatusCode.ERROR, str(e)))
                raise
            _handle_call(span, kwargs, response, metric_params, event_logger)
            return response

    return with_instrumentation

def new_span(
    self,
    id_: str,
    bound_args: inspect.BoundArguments,
    instance: Optional[Any] = None,
    parent_span_id: Optional[str] = None,
    tags: Optional[Dict[str, Any]] = None,
    **kwargs: Any,
) -> Optional[SpanHolder]:
    """Create a span."""
    # Take the class name and method name from id_ where id_ is e.g.
    # 'SentenceSplitter.split_text_metadata_aware-a2f2a780-2fa6-4682-a88e-80dc1f1ebe6a'
    matches = CLASS_ANDMETHOD_NAME_FROM_ID_REGEX.match(id_)
    class_name = matches.groups()[0]
    method_name = matches.groups()[1]

    parent = self.open_spans.get(parent_span_id)

    if class_name in AVAILABLE_OPENLLMETRY_INSTRUMENTATIONS:
        token = context_api.attach(
            context_api.set_value(
                SUPPRESS_LANGUAGE_MODEL_INSTRUMENTATION_KEY, False
            )
        )
        return SpanHolder(id_, parent, token=token)

    kind = (
        TraceloopSpanKindValues.TASK.value
        if parent
        else TraceloopSpanKindValues.WORKFLOW.value
    )

    if isinstance(instance, Workflow):
        span_name = (
            f"{instance.__class__.__name__}.{kind}"
            if not parent_span_id
            else f"{method_name}.{kind}"
        )
    else:
        span_name = f"{class_name}.{kind}"

    span = self._tracer.start_span(
        span_name,
        context=parent.context if parent else None,
    )
    current_context = set_span_in_context(
        span, context=parent.context if parent else None
    )
    current_context = context_api.set_value(
        SUPPRESS_LANGUAGE_MODEL_INSTRUMENTATION_KEY,
        True,
        current_context,
    )
    token = context_api.attach(current_context)

    span.set_attribute(SpanAttributes.TRACELOOP_SPAN_KIND, kind)
    span.set_attribute(SpanAttributes.TRACELOOP_ENTITY_NAME, span_name)
    try:
        if should_send_prompts():
            span.set_attribute(
                SpanAttributes.TRACELOOP_ENTITY_INPUT,
                json.dumps(bound_args.arguments, cls=JSONEncoder),
            )
    except Exception:
        pass

    # Extract tool information for call_tool spans (workflow-based agents)
    if method_name == "call_tool":
        try:
            # The 'ev' argument is a WorkflowToolCall event
            ev = bound_args.arguments.get("ev")
            if ev and isinstance(ev, WorkflowToolCall):
                span.set_attribute("tool.name", ev.tool_name)
                span.set_attribute(
                    "tool.arguments",
                    json.dumps(ev.tool_kwargs, cls=JSONEncoder)
                )
        except Exception:
            pass

    return SpanHolder(id_, parent, span, token, current_context)
